import{_ as r,r as n,o as c,c as l,e as t,a,d as e,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Настройка Планировщика - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как запускать запланированные задачи и очереди.","frontmatter":{"subtitle":"Узнайте, как запускать запланированные задачи и очереди."},"headers":[{"level":2,"title":"Настройка обработчиков очередей","slug":"настроика-обработчиков-очередеи","link":"#настроика-обработчиков-очередеи","children":[]},{"level":2,"title":"Cron без командной строки","slug":"cron-без-команднои-строки","link":"#cron-без-команднои-строки","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/setup/scheduler.md","filePath":"3.x/ru/setup/scheduler.md"}'),d={name:"3.x/ru/setup/scheduler.md"};function u(h,s,g,k,m,v){const o=n("pre-heading"),p=n("post-heading");return c(),l("div",null,[t(o),s[0]||(s[0]=a("h1",null,"Настройка Планировщика",-1)),t(p),s[1]||(s[1]=a("p",null,[e("Для корректной работы запланированных задач добавьте следующее "),a("a",{href:"https://www.cyberciti.biz/faq/how-do-i-add-jobs-to-cron-under-linux-or-unix-oses/",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("задание Cron"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),a("span",{class:"sr-only"},"(opens new window)")])]),e(" на сервер:")],-1)),s[2]||(s[2]=i(`<div class="language-bash extra-class"><pre class="language-bash"><code>* * * * * php /october/artisan schedule:run <span class="token operator">&gt;&gt;</span> /dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre></div><p>Обязательно замените <code>/october/artisan</code> на абсолютный путь к файлу artisan в каталоге установки October CMS. Это задание cron будет вызывать планировщик команд каждую минуту. Затем October CMS проверяет все запланированные задачи и выполняет те, для которых наступило время.</p><div class="custom-block tip"><p>При добавлении файла crontab в /etc/cron.d укажите имя пользователя после <code>* * * * *</code>:</p><div class="language-bash extra-class"><pre class="language-bash"><code>* * * * * alice php /october/artisan schedule:run <span class="token operator">&gt;&gt;</span> /dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre></div></div><h2 id="настроика-обработчиков-очередеи"><a href="#настроика-обработчиков-очередеи" class="header-anchor">#</a> Настройка обработчиков очередей</h2><p>При необходимости можно настроить драйвер очередей для обработки <a href="./../extend/services/queue.html">заданий в очереди</a>. Драйвер очередей настраивается в файле <code>config/queue.php</code>.</p><p>Для драйвера очередей на основе базы данных можно настроить задание cron, выполняющее команду, которая обрабатывает первое доступное задание в очереди: <code>php artisan queue:work --once</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>* * * * * php /october/artisan queue:work <span class="token parameter variable">--once</span> <span class="token operator">&gt;&gt;</span> /dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre></div><p>В качестве альтернативы можно запустить очередь как фоновый процесс-демон:</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan queue:work
</code></pre></div><h2 id="cron-без-команднои-строки"><a href="#cron-без-команднои-строки" class="header-anchor">#</a> Cron без командной строки</h2><p>Если ваш хостинг-провайдер не предоставляет доступ к таблице cron, можно вместо этого вызывать публичный URL каждые X минут. Например, если плагин требует выполнения следующей команды каждые 15 минут:</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan campaign:run
</code></pre></div><p>Для решения этой задачи потребуется написать PHP-код, используя фасад <code>Artisan</code> вместе с <a href="./../extend/system/routing.html">файлом маршрутов</a> для создания конечной точки, вызывающей эту команду. Например, файл <strong>routes.php</strong> может содержать следующее:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/campaign-run&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Artisan</span><span class="token operator">::</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;campaign:run&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>При открытии URL <code>/campaign-run</code> будет вызвана artisan-команда.</p><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../extend/system/scheduling.html">Планирование задач</a></li><li><a href="./../extend/services/queue.html">Очереди</a></li></ul></div>`,17))])}const x=r(d,[["render",u]]);export{b as __pageData,x as default};
